INSERT OR IGNORE INTO podcasts_shows (titulo, slug, descricao, capa_url, spotify_url, spotify_uri, categoria, idioma, ativo) VALUES ('Lino Conversa: Vozes de Angola e Educação Aberta', 'lino-conversa', 'Entrevistas, debates e conversas inspiradoras com educadores, autores, estudantes e inovadores angolanos sobre a democratização do conhecimento e o futuro da juventude africana.', 'https://images.unsplash.com/photo-1590602847861-f357a9332bbc?w=600&auto=format&fit=crop&q=80', 'https://open.spotify.com/show/4rOoJ6Egrf8K2IrywzwOMk', 'spotify:show:4rOoJ6Egrf8K2IrywzwOMk', 'Educação & Diálogos', 'pt', 1);
INSERT OR IGNORE INTO podcasts_episodios (show_id, numero, titulo, slug, descricao, duracao_minutos, spotify_url, spotify_embed_url, audio_url, publicado_em, reproducoes) VALUES ((SELECT id FROM podcasts_shows WHERE slug = 'lino-conversa'), 1, 'Ep. 01 — A Revolução dos Livros Livres e da Educação Aberta em Angola', 'lino-conversa-ep01-revolucao-livros-livres', 'Uma reflexão profunda sobre o impacto do acesso livre a livros, artigos e cursos digitais na vida de estudantes e jovens pesquisadores em Angola.', 28, 'https://open.spotify.com/episode/7mK9y0Wb3X2Z1bY4vQ9wRe', 'https://open.spotify.com/embed/episode/7mK9y0Wb3X2Z1bY4vQ9wRe?utm_source=generator', NULL, '2026-10-01', 0);
INSERT OR IGNORE INTO podcasts_episodios (show_id, numero, titulo, slug, descricao, duracao_minutos, spotify_url, spotify_embed_url, audio_url, publicado_em, reproducoes) VALUES ((SELECT id FROM podcasts_shows WHERE slug = 'lino-conversa'), 2, 'Ep. 02 — Inteligência Artificial, Carreira Tech e Oportunidades em África', 'lino-conversa-ep02-ia-carreira-tech-africa', 'Como a juventude africana pode aproveitar ferramentas abertas, roadmaps e comunidades de tecnologia para criar soluções de impacto e gerar renda.', 34, 'https://open.spotify.com/episode/2kL8p1Wc5V3X0aB8cD1eRf', 'https://open.spotify.com/embed/episode/2kL8p1Wc5V3X0aB8cD1eRf?utm_source=generator', NULL, '2026-10-05', 0);
INSERT OR IGNORE INTO podcasts_episodios (show_id, numero, titulo, slug, descricao, duracao_minutos, spotify_url, spotify_embed_url, audio_url, publicado_em, reproducoes) VALUES ((SELECT id FROM podcasts_shows WHERE slug = 'lino-conversa'), 3, 'Ep. 03 — Preservação das Línguas Nacionais e Tradição Oral na Era Digital', 'lino-conversa-ep03-linguas-nacionais-tradicao-oral', 'O papel da literatura digital, dos audiolivros e da tecnologia na valorização do Kimbundu, Umbundu, Cokwe e de todo o património ancestral.', 31, 'https://open.spotify.com/episode/5aB7c8D9e0F1g2H3i4J5k6', 'https://open.spotify.com/embed/episode/5aB7c8D9e0F1g2H3i4J5k6?utm_source=generator', NULL, '2026-10-09', 0);
INSERT OR IGNORE INTO podcasts_shows (titulo, slug, descricao, capa_url, spotify_url, spotify_uri, categoria, idioma, ativo) VALUES ('Livro da Semana: Resenhas & Clássicos em Áudio', 'livro-da-semana', 'Guias de leitura, análises de contexto histórico e resenhas profundas das maiores obras literárias angolanas, africanas e universais disponíveis no acervo do Lino Livre.', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=600&auto=format&fit=crop&q=80', 'https://open.spotify.com/show/2MAi0BvDc6GTFvK2Lp4mNz', 'spotify:show:2MAi0BvDc6GTFvK2Lp4mNz', 'Literatura & Crítica', 'pt', 1);
INSERT OR IGNORE INTO podcasts_episodios (show_id, numero, titulo, slug, descricao, duracao_minutos, spotify_url, spotify_embed_url, audio_url, publicado_em, reproducoes) VALUES ((SELECT id FROM podcasts_shows WHERE slug = 'livro-da-semana'), 1, 'Ep. 01 — Sagrada Esperança (Agostinho Neto): A Poesia da Dignidade e Liberdade', 'livro-semana-ep01-sagrada-esperanca-agostinho-neto', 'Análise detalhada dos poemas fundacionais da luta angolana, a metáfora da esperança e o valor da soberania cultural na voz do poeta maior.', 18, 'https://open.spotify.com/episode/3xY8z1Wb4V2Z0aC7cD2eSf', 'https://open.spotify.com/embed/episode/3xY8z1Wb4V2Z0aC7cD2eSf?utm_source=generator', NULL, '2026-09-28', 0);
INSERT OR IGNORE INTO podcasts_episodios (show_id, numero, titulo, slug, descricao, duracao_minutos, spotify_url, spotify_embed_url, audio_url, publicado_em, reproducoes) VALUES ((SELECT id FROM podcasts_shows WHERE slug = 'livro-da-semana'), 2, 'Ep. 02 — Dom Casmurro (Machado de Assis): O Enigma de Capitu Desvendado', 'livro-semana-ep02-dom-casmurro-machado-assis', 'Um passeio pela mente obsessiva de Bento Santiago, a ironia machadiana e os contrastes entre memória, ciúme e verdade.', 22, 'https://open.spotify.com/episode/4aB9c0D1e2F3g4H5i6J7k8', 'https://open.spotify.com/embed/episode/4aB9c0D1e2F3g4H5i6J7k8?utm_source=generator', NULL, '2026-10-02', 0);
INSERT OR IGNORE INTO podcasts_episodios (show_id, numero, titulo, slug, descricao, duracao_minutos, spotify_url, spotify_embed_url, audio_url, publicado_em, reproducoes) VALUES ((SELECT id FROM podcasts_shows WHERE slug = 'livro-da-semana'), 3, 'Ep. 03 — As Aventuras de Ngunga (Pepetela): A Travessia de um Jovem na Luta', 'livro-semana-ep03-aventuras-ngunga-pepetela', 'A jornada comovente de Ngunga pelas matas do leste de Angola, descobrindo o valor da solidariedade, do conhecimento e do futuro.', 19, 'https://open.spotify.com/episode/6dE7f8G9h0I1j2K3l4M5n6', 'https://open.spotify.com/embed/episode/6dE7f8G9h0I1j2K3l4M5n6?utm_source=generator', NULL, '2026-10-06', 0);
INSERT OR IGNORE INTO podcasts_episodios (show_id, numero, titulo, slug, descricao, duracao_minutos, spotify_url, spotify_embed_url, audio_url, publicado_em, reproducoes) VALUES ((SELECT id FROM podcasts_shows WHERE slug = 'livro-da-semana'), 4, 'Ep. 04 — Things Fall Apart (Chinua Achebe): A Grande Tragédia da Ruptura Cultural', 'livro-semana-ep04-things-fall-apart-chinua-achebe', 'Como a obra-prima de Achebe transformou a literatura mundial ao narrar a resistência e a complexidade da sociedade tradicional igbo.', 25, 'https://open.spotify.com/episode/8oP9q0R1s2T3u4V5w6X7y8', 'https://open.spotify.com/embed/episode/8oP9q0R1s2T3u4V5w6X7y8?utm_source=generator', NULL, '2026-10-10', 0);
INSERT OR IGNORE INTO podcasts_shows (titulo, slug, descricao, capa_url, spotify_url, spotify_uri, categoria, idioma, ativo) VALUES ('Histórias ao Luar: Contos & Mitos Africanos', 'historias-ao-luar', 'Leituras dramatizadas, mitos ancestrais dos povos bantos e fábulas da tradição oral africana narradas para encantar famílias e resgatar a sabedoria dos mais velhos.', 'https://images.unsplash.com/photo-1509198397868-475647b2a1e5?w=600&auto=format&fit=crop&q=80', 'https://open.spotify.com/show/1kLqPo8m3X2Z1bY4vQ9wRe', 'spotify:show:1kLqPo8m3X2Z1bY4vQ9wRe', 'Contos & Tradição Oral', 'pt', 1);
INSERT OR IGNORE INTO podcasts_episodios (show_id, numero, titulo, slug, descricao, duracao_minutos, spotify_url, spotify_embed_url, audio_url, publicado_em, reproducoes) VALUES ((SELECT id FROM podcasts_shows WHERE slug = 'historias-ao-luar'), 1, 'Ep. 01 — Contos Populares de Angola: A Lebre Esperta e o Leopardo', 'historias-luar-ep01-contos-angola-lebre-leopardo', 'A clássica narrativa da etnoliteratura quimbundo recolhida por Héli Chatelain, ensinando como a inteligência supera a força bruta.', 15, 'https://open.spotify.com/episode/1aB2c3D4e5F6g7H8i9J0k1', 'https://open.spotify.com/embed/episode/1aB2c3D4e5F6g7H8i9J0k1?utm_source=generator', NULL, '2026-09-25', 0);
INSERT OR IGNORE INTO podcasts_episodios (show_id, numero, titulo, slug, descricao, duracao_minutos, spotify_url, spotify_embed_url, audio_url, publicado_em, reproducoes) VALUES ((SELECT id FROM podcasts_shows WHERE slug = 'historias-ao-luar'), 2, 'Ep. 02 — A Sabedoria de Anansi: Por Que as Histórias Pertencem ao Povo', 'historias-luar-ep02-sabedoria-anansi-africa-ocidental', 'A fascinante lenda dos povos axante de como a aranha Anansi conquistou a caixa de histórias do deus do céu Nyame para libertar o conhecimento na Terra.', 14, 'https://open.spotify.com/episode/2bC3d4E5f6G7h8I9j0K1l2', 'https://open.spotify.com/embed/episode/2bC3d4E5f6G7h8I9j0K1l2?utm_source=generator', NULL, '2026-10-03', 0);
INSERT OR IGNORE INTO podcasts_episodios (show_id, numero, titulo, slug, descricao, duracao_minutos, spotify_url, spotify_embed_url, audio_url, publicado_em, reproducoes) VALUES ((SELECT id FROM podcasts_shows WHERE slug = 'historias-ao-luar'), 3, 'Ep. 03 — A Epopeia de Sundiata: O Rei Leão do Império do Mali', 'historias-luar-ep03-epopeia-sundiata-imperio-mali', 'A lendária narrativa dos griots mandingas sobre a infância desafiadora, a coragem e a unificação das tribos sob o grande Sundiata Keita.', 21, 'https://open.spotify.com/episode/3cD4e5F6g7H8i9J0k1L2m3', 'https://open.spotify.com/embed/episode/3cD4e5F6g7H8i9J0k1L2m3?utm_source=generator', NULL, '2026-10-08', 0);
INSERT OR IGNORE INTO podcasts_shows (titulo, slug, descricao, capa_url, spotify_url, spotify_uri, categoria, idioma, ativo) VALUES ('Dica Rápida em Áudio: Estudos, Foco & Produtividade', 'dica-rapida-audio', 'Cápsulas de áudio objetivas de 3 a 5 minutos com técnicas práticas de estudo, foco mental, preparação para exames e ferramentas gratuitas de produtividade.', 'https://images.unsplash.com/photo-1434030216411-0b793f4b4173?w=600&auto=format&fit=crop&q=80', 'https://open.spotify.com/show/3wKmX7sP4V2Y0aB8cD1eRf', 'spotify:show:3wKmX7sP4V2Y0aB8cD1eRf', 'Produtividade & Estudo', 'pt', 1);
INSERT OR IGNORE INTO podcasts_episodios (show_id, numero, titulo, slug, descricao, duracao_minutos, spotify_url, spotify_embed_url, audio_url, publicado_em, reproducoes) VALUES ((SELECT id FROM podcasts_shows WHERE slug = 'dica-rapida-audio'), 1, 'Ep. 01 — Técnica Pomodoro e Leitura Ativa: Como Reter Mais Conteúdo', 'dica-rapida-ep01-pomodoro-leitura-ativa', 'Aprenda a intercalar blocos de 25 minutos de estudo focado com pausas revigorantes para nunca mais se cansar ao ler.', 4, 'https://open.spotify.com/episode/4dE5f6G7h8I9j0K1l2M3n4', 'https://open.spotify.com/embed/episode/4dE5f6G7h8I9j0K1l2M3n4?utm_source=generator', NULL, '2026-10-04', 0);
